  ('AUS-CAT-CORVOX', NULL, 'AUS', 'Corvo X small UAS', 'Corvo X', 'air', 'isr', NULL, NULL, 'blue', 'Australian-made fixed-wing VTOL small UAS bought under DEF129 Phase 4B. Entry into service announced 7 May 2026; replaces Wasp AE.', 'high', '{"Australian Defence Magazine, May 2026: https://www.australiandefence.com.au/defence/land/sypaq-systems-corvo-x-enters-into-service","sUAS News, May 2026: https://www.suasnews.com/2026/05/sypaq-systems-announces-successful-delivery-and-entry-into-service-of-corvo-x/"}', 'sypaq-corvo-x', true, 'Australia', 'SYPAQ Systems', 'in_service', 2026, 'fielded'),
  ('AUS-CAT-VECTOR', NULL, 'AUS', 'Vector AI VTOL small UAS', 'Vector AI', 'air', 'isr', NULL, NULL, 'blue', 'Fixed-wing eVTOL ISR drone. Two DEF129 contracts worth A$90m (Apr 2024), assembled in Queensland. Army operating Vector AI from 2026, including at Exercise Black Prince 3 (May 2026, Cultana).', 'high', '{"Quantum Systems release, Apr 2024: https://www.prnewswire.com/news-releases/quantum-systems-inc-awarded-two-contracts-by-commonwealth-of-australia-for-def129-suas-totaling-aud-90-million-302196166.html","Janes, 9 Jul 2026: https://www.janes.com/defence-intelligence-insights/defence-news/defence/australia-fields-vector-ai-surveillance-uav","Defence Connect, 24 Sep 2026: https://www.defenceconnect.com.au/land/18907-australian-army-accelerating-drone-warfare-integration-towards-talisman-sabre-2027-debut"}', 'quantum-vector-ai-isr-rsta', true, 'Australia', 'Quantum Systems', 'in_service', NULL, 'fielded'),
  ('AUS-CAT-R70', NULL, 'AUS', 'SkyRanger R70 quadcopter', 'SkyRanger R70', 'air', 'isr', NULL, NULL, 'blue', 'Small quadcopter ISR drone used by RAAF No. 3 Security Forces Squadron after about three years of trials (Defence, Nov 2020). Contract value and quantity not published.', 'medium', '{"Defence news, 17 Nov 2020: https://www.defence.gov.au/news-events/news/2020-11-17/sky-ranger-innovation-target","Asian Military Review, Aug 2025: https://www.asianmilitaryreview.com/2025/08/keeping-up-with-the-droneses-australia-advances-its-c-uas-capabilities-foc/"}', 'teledyne-flir-skyranger-r70', true, 'Australia', 'Teledyne FLIR', 'in_service', NULL, 'fielded'),
  ('AUS-CAT-INTEGRATOR', NULL, 'AUS', 'Integrator tactical UAS (LAND 129 Phase 3)', 'Integrator', 'air', 'isr', NULL, NULL, 'blue', 'Runway-independent fixed-wing tactical UAS; 24 aircraft under LAND 129 Phase 3, built by Insitu Pacific in Queensland. Replaced the RQ-7B Shadow 200 with 20th Regiment RAA; training began Jul 2022.', 'high', '{"Defence project page: https://www.defence.gov.au/defence-activities/projects/tactical-uncrewed-aerial-system","Defence news, 15 Jul 2025: https://www.defence.gov.au/news-events/news/2025-07-15/demand-drone-operators-set-soar"}', 'insitu-integrator-isr', true, 'Australia', 'Insitu (Boeing)', 'in_service', NULL, 'fielded'),
  ('AUS-CAT-SWITCHBLADE300', NULL, 'AUS', 'Switchblade 300 loitering munition', 'Switchblade 300', 'air', 'other', NULL, NULL, 'blue', 'Man-portable loitering munition bought through US Foreign Military Sales, announced 8 Jul 2024. Defence planned first delivery in late 2024 and service entry in 2025. Variant not named by Defence (Block 20 reported).', 'high', '{"Defence Ministers release, 8 Jul 2024: https://www.minister.defence.gov.au/media-releases/2024-07-08/australian-government-announces-acquisition-precision-loitering-munition","Janes, Jul 2024: https://www.janes.com/defence-intelligence-insights/defence-news/air/australia-procures-switchblade-loitering-munition"}', 'switchblade-300', true, 'Australia', 'AeroVironment', 'ordered', NULL, 'fielded'),
  ('AUS-CAT-OWLB', NULL, 'AUS', 'OWL-B loitering munition', 'OWL-B', 'air', 'other', NULL, NULL, 'blue', 'Australian electric loitering munition in development and trial under ASCA Mission Talon-Strike (A$20.8m, 18 months, Oct 2025). Maritime trials from MV Sycamore. Service entry targeted for 2027.', 'medium', '{"ASCA post, Oct 2025: https://www.linkedin.com/posts/asca-aus_ascaaus-youadf-innovation-activity-7384099733864267776-J6kz","Janes, Nov 2025: https://www.janes.com/osint-insights/defence-news/sea/indo-pacific-2025-australia-conducts-maritime-trials-of-owl-b-loitering-munition","Australian Defence Magazine, Sep 2026: https://www.australiandefence.com.au/news/news/innovaero-to-list-on-asx"}', 'innovaero-owl-b', true, 'Australia', 'Innovaero', 'in_development', NULL, 'emd'),
  ('AUS-CAT-FPVSTRIKE', NULL, 'AUS', 'Explosive FPV strike drone teams (Army RAS)', 'Army FPV teams', 'air', 'other', NULL, NULL, 'blue', 'Four-person teams (leader, 2IC, operator, navigator). Explosive FPV drones under $5,000 with about 20 km reach using repeater drones. 5/7 RAR fields an FPV strike combat team at Talisman Sabre 2027.', 'medium', '{"Defence Connect, 24 Sep 2026: https://www.defenceconnect.com.au/land/18907-australian-army-accelerating-drone-warfare-integration-towards-talisman-sabre-2027-debut","Defence Connect, 17 Aug 2026: https://www.defenceconnect.com.au/land/18726-australian-army-to-field-fpv-strike-drone-team-for-talisman-sabre-2027"}', NULL, true, 'Australia', 'Various (Army-built and commercial)', 'in_development', NULL, 'r_and_d'),
  ('AUS-CAT-LAND156', NULL, 'AUS', 'LAND 156 counter-UAS systems', 'LAND 156 C-UAS', 'ground', 'other', NULL, NULL, 'blue', 'Army counter-drone program. First wave (Jul 2025): $16.9m to 11 vendors, including DroneShield DroneGun Mk4 and RfPatrol. Leidos Australia is systems integrator (Aug 2025) with Acacia Systems Cortex C2, Department 13 DART and Echodyne radar; the suite, with L3Harris VAMPIRE and an EOS R400 Slinger on Hawkei, first live-fired at Exercise Southern Arrow 25 (Dec 2025, Cultana). Silentium MAVERICK M8 passive radar selected Jan 2026. Portable kits (Dronebuster, KeyOptions SkyControl, RfPatrol Mk2) used at Exercise Austral Shield (Jul 2026).', 'high', '{"Defence news, 24 Dec 2025: https://www.defence.gov.au/news-events/news/2025-12-24/army-tests-counter-drone-technology","CONTACT (Defence story), 8 Aug 2026: https://contactairlandandsea.com/2026/08/08/counter-drone-tech-tested-on-aussie-exercise/","Australian Defence Magazine, Jul 2025: https://www.australiandefence.com.au/defence/land/popular-ukrainian-drone-detector-amongst-land-156-winners","Australian Defence Magazine, Aug 2025: https://www.australiandefence.com.au/defence/land/leidos-selected-as-land-156-systems-integrator","Australian Defence Magazine, Jan 2026: https://www.australiandefence.com.au/news/news/silentium-passive-radar-selected-for-land-156"}', NULL, true, 'Australia', 'Leidos Australia (systems integrator)', 'in_service', NULL, 'lrip'),
  ('AUS-CAT-SYRACUSE', NULL, 'AUS', 'ASCA Mission Syracuse counter-drone effectors', 'Mission Syracuse', 'ground', 'other', NULL, NULL, 'blue', 'A$37.4m of ASCA contracts for lower-cost drone defeat: AIM Defence Fractl high-energy laser (A$21.3m) and SYPAQ Corvo Strike interceptor drone (A$10.4m), both 21 Apr 2026, and an EOS R400 Slinger (A$5.7m, 8 Jul 2026). Fractl is to be integrated with LAND 156 C2.', 'high', '{"Defense News, 24 Apr 2026: https://www.defensenews.com/global/asia-pacific/2026/04/24/australia-awards-contracts-for-counter-drone-tech-based-on-lasers-interceptors/","Defence Ministers release, 8 Jul 2026 (copy): https://www.globalsecurity.org/wmd/library/news/australia/2026/australia-260708-audod05.htm"}', NULL, true, 'Australia', 'AIM Defence / SYPAQ Systems / EOS', 'in_development', NULL, 'emd')
ON CONFLICT (id) DO UPDATE SET
  designation = EXCLUDED.designation, short_name = EXCLUDED.short_name, domain = EXCLUDED.domain,
  role = EXCLUDED.role, force_side = EXCLUDED.force_side, open_source_summary = EXCLUDED.open_source_summary,
