  ('AUS-CAT-HUNTER', 'SEA 5000 Hunter-class frigate', 'BAE Systems Australia', '{"GBR"}', NULL, 'est. early 2030s', '{"anti-submarine warfare","CEAFAR2 L-band AESA","Aegis + SAAB 9LV"}', 'Batch 1 of 6 building at Osborne; scope reduced under the 2024 Surface Fleet Review.', 'high', '{"RAN; Australian Defence Magazine"}'),
  ('AUS-CAT-NEWFFM', 'SEA 3000 general purpose frigate', 'Mitsubishi Heavy Industries', '{"JPN"}', NULL, 'First ship delivery 2029', '{"multi-mission","reduced crew","first three Japan-built, later hulls in WA","SeaRAM self-defence"}', 'Australia’s first major surface combatant acquisition from Japan.', 'high', '{"Defence Ministers release, 18 Apr 2026: https://www.minister.defence.gov.au/media-releases/2026-04-18/australia-locks-delivery-our-first-three-general-purpose-frigates"}'),
