  ('AUS-CAT-MRGBAD', 'AIR 6502 medium-range GBAD (candidate)', NULL, '{"USA"}', 'Live fire Jun 2026 (achieved)', NULL, '{"SM-2 effector","CEA radar to Aegis integration","towed Derringer launcher"}', 'IIP 2026 directed acceleration of a medium-range ground-based air defence capability.', 'high', '{"Defence Ministers release, 9 Jul 2026: https://www.minister.defence.gov.au/media-releases/2026-07-09/australia-achieves-landmark-prototype-missile-defence-live-fire"}'),
